import{_ as t,o as s,c as o,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"职场观察","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/career-observation/index.md","filePath":"topics/career-observation/index.md"}'),e={name:"topics/career-observation/index.md"};function p(r,a,l,i,u,d){return s(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="职场观察" tabindex="-1">职场观察 <a class="header-anchor" href="#职场观察" aria-label="Permalink to &quot;职场观察&quot;">​</a></h1><blockquote><p>整理自各类视频、播客、书籍中的职场观察与洞察</p></blockquote><hr><h2 id="核心议题" tabindex="-1">核心议题 <a class="header-anchor" href="#核心议题" aria-label="Permalink to &quot;核心议题&quot;">​</a></h2><h3 id="_1-职场高情商沟通公式" tabindex="-1">1. 职场高情商沟通公式 <a class="header-anchor" href="#_1-职场高情商沟通公式" aria-label="Permalink to &quot;1. 职场高情商沟通公式&quot;">​</a></h3><p><strong>核心：</strong> 沟通的本质不是&quot;说什么&quot;，是&quot;让对方愿意听、愿意做&quot;。</p><p>→ 详见：<code>index.md</code>（9大沟通公式）</p><h3 id="_2-ai时代的职场悖论" tabindex="-1">2. AI时代的职场悖论 <a class="header-anchor" href="#_2-ai时代的职场悖论" aria-label="Permalink to &quot;2. AI时代的职场悖论&quot;">​</a></h3><p><strong>核心：</strong> 效率提升反被裁员，工贼困境，33岁斩杀线。</p><p>→ 详见：<code>ai-workplace-paradox.md</code></p><h3 id="_3-反差能力-ai时代传统从业者的新叙事" tabindex="-1">3. 反差能力：AI时代传统从业者的新叙事 <a class="header-anchor" href="#_3-反差能力-ai时代传统从业者的新叙事" aria-label="Permalink to &quot;3. 反差能力：AI时代传统从业者的新叙事&quot;">​</a></h3><p><strong>核心：</strong> 不在于成为AI专家，而在于找到AI替代不了的需求——情感共鸣、身份认同、认知对话——并用已有技能去服务它。</p><p>→ 详见：<code>reverse-ability-ai-era.md</code></p><h3 id="_4-新旧企业家思维对比-年轻人破局框架" tabindex="-1">4. 新旧企业家思维对比 &amp; 年轻人破局框架 <a class="header-anchor" href="#_4-新旧企业家思维对比-年轻人破局框架" aria-label="Permalink to &quot;4. 新旧企业家思维对比 &amp; 年轻人破局框架&quot;">​</a></h3><p><strong>核心：</strong> 房地产&quot;后开发时代&quot;（人均GDP 1万美元拐点）、古早类 vs AI时代企业家代际差异、三字诀（挪地→入局→改认知）。</p><p>→ 详见：<code>old-vs-new-entrepreneur-mindset.md</code></p><h3 id="_5-agent开发岗-核心是工程质量" tabindex="-1">5. Agent开发岗：核心是工程质量 <a class="header-anchor" href="#_5-agent开发岗-核心是工程质量" aria-label="Permalink to &quot;5. Agent开发岗：核心是工程质量&quot;">​</a></h3><p><strong>核心：</strong> 腾讯Agent开发岗真不是调Prompt，是工程能力——生产级代码、成本核算、效果验证、完整上线链路。岗位本质是招&quot;独当一面&quot;的工程师（有后端经验优先）。</p><p>→ 详见：<code>agent-development-engineering-core.md</code></p><h3 id="_6-ai-时代的个人跃迁-从-提效-到-能力构建" tabindex="-1">6. AI 时代的个人跃迁：从&quot;提效&quot;到&quot;能力构建&quot; <a class="header-anchor" href="#_6-ai-时代的个人跃迁-从-提效-到-能力构建" aria-label="Permalink to &quot;6. AI 时代的个人跃迁：从&quot;提效&quot;到&quot;能力构建&quot;&quot;">​</a></h3><p><strong>核心：</strong> 访谈的方法层（喂足个人上下文、让 AI&quot;泼冷水&quot;、多账号后台并行）+ 心智层（从&quot;提效&quot;到&quot;能力构建&quot;：把不擅长的交给 AI，专注核心优势）。本库补了两处硬核实：<strong>METR 随机对照试验</strong>（资深开发者在自己熟悉 5 年的项目上用 AI，实测<strong>慢 19%</strong>，而事前预期 -24%、事后自评 -20%）与<strong>谄媚是训练出来的</strong>（arXiv:2310.13548，五个 SOTA 助手一致谄媚）；并指出&quot;多账号并行&quot;与&quot;外脑累积&quot;是<strong>吞吐 vs 复利</strong>的结构冲突。</p><p>→ 详见：<code>ai-leverage-playbook.md</code></p><h3 id="_7-马兆远访谈核实-ai-时代的内卷、教育与-月球工业伴星" tabindex="-1">7. 马兆远访谈核实：AI 时代的内卷、教育与&quot;月球工业伴星&quot; <a class="header-anchor" href="#_7-马兆远访谈核实-ai-时代的内卷、教育与-月球工业伴星" aria-label="Permalink to &quot;7. 马兆远访谈核实：AI 时代的内卷、教育与&quot;月球工业伴星&quot;&quot;">​</a></h3><p><strong>核心：</strong> 南方科技大学教授<strong>马兆远</strong>（牛津物理博士、2009 中科院研究员、<strong>为天宫四号设计载荷</strong>）谈：内卷根源=<strong>缺社会安全感</strong>（住房/教育/医疗）、<strong>赛道思维 → 花园思维</strong>、体育+动手能力 → 心流、<strong>将错就错</strong>。<strong>核实结论：人物身份完全属实（履历比视频所述更强），观点类本无&quot;真伪&quot;只有归属问题；唯一硬伤在收尾的&quot;月球工业伴星&quot;构想存在时间错位</strong> —— 1979-04-30 NASA 报告已给出量化方案（30 座 × 10 GW），且当前工程路线是 GEO 而非月球。</p><p>→ 详见：<code>ma-zhaoyuan-interview-ai-involution.md</code></p><h3 id="_8-美发店创始人-×《魔兽世界》低谷翻身故事核实" tabindex="-1">8. 美发店创始人 ×《魔兽世界》低谷翻身故事核实 <a class="header-anchor" href="#_8-美发店创始人-×《魔兽世界》低谷翻身故事核实" aria-label="Permalink to &quot;8. 美发店创始人 ×《魔兽世界》低谷翻身故事核实&quot;">​</a></h3><p><strong>核心：</strong> 转来的故事（中年破产 → 靠妻子养活 → 玩&quot;无人问津的治疗职业&quot;苦练半年 → 团队将散时带通关 → 重拾信心）<strong>在公开网络上零命中</strong>：Bing 原样返回&quot;没有与此相关的结果&quot;、Google News 零命中、搜狗 11,210 条全是<strong>同名网络小说</strong>（《林小龙 叶小五》，作者龙刀风剑）、B站检索被 HTTP 412 风控。<strong>判定为第 ⑤ 类失真（无具名信源）</strong>——框架可当&quot;叙事类型&quot;，人物与细节不可采信。★ 但被故事勾出的两个问题有硬答案：① <strong>德鲁伊确实是治疗职业</strong>（6 个治疗职业之一，<code>warcraft.wiki.gg/wiki/Healer</code> 实测）；② &quot;<strong>人需要一次成功来恢复心气</strong>&quot;＝Bandura 自我效能感理论中排<strong>第一位</strong>、<strong>最强</strong>的来源（enactive mastery 亲历成败），配套机制是<strong>习得性无助的逆转靠重建可控感</strong>。★ &quot;妻子养活&quot;不是配角，是社会缓冲（经济 + 情绪），<strong>没有它就没有那半年</strong>。</p><p>→ 详见：<code>lin-xiaolong-wow-story-verification.md</code></p><hr><h2 id="主题索引" tabindex="-1">主题索引 <a class="header-anchor" href="#主题索引" aria-label="Permalink to &quot;主题索引&quot;">​</a></h2><hr><h2 id="一、为什么沟通有公式" tabindex="-1">一、为什么沟通有公式 <a class="header-anchor" href="#一、为什么沟通有公式" aria-label="Permalink to &quot;一、为什么沟通有公式&quot;">​</a></h2><blockquote><p>职场沟通的本质不是&quot;说什么&quot;，是&quot;让对方愿意听、愿意做&quot;。</p></blockquote><ul><li><strong>好沟通</strong>：推动事情往前走，关系还更好</li><li><strong>坏沟通</strong>：事情没推动，双方还结仇</li><li><strong>核心心法</strong>：先解决情绪，再解决事情</li></ul><p><strong>通用原则</strong>：</p><ul><li>任何沟通，先说结论</li><li>任何批评，先说事实</li><li>任何冲突，先通情再说理</li></ul><hr><h2 id="二、9大沟通公式" tabindex="-1">二、9大沟通公式 <a class="header-anchor" href="#二、9大沟通公式" aria-label="Permalink to &quot;二、9大沟通公式&quot;">​</a></h2><h3 id="公式1-汇报-结论先行-理由-数据支撑" tabindex="-1">公式1：汇报 = 结论先行 + 理由 + 数据支撑 <a class="header-anchor" href="#公式1-汇报-结论先行-理由-数据支撑" aria-label="Permalink to &quot;公式1：汇报 = 结论先行 + 理由 + 数据支撑&quot;">​</a></h3><p><strong>场景</strong>：领导问你工作进展</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;这个项目是这样的，我们之前开了好几次会，讨论了很多方案，中间还遇到了一些问题，后来又改了一版，所以有点delay……&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;项目Delay了3天（结论）。原因是客户临时增加了需求（理由）。目前已完成85%，预计周五能交付（数据+计划）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>结论：……（一句话说清楚）</span></span>
<span class="line"><span>原因：……（1-2句话）</span></span>
<span class="line"><span>数据：……（关键数字）</span></span>
<span class="line"><span>计划：接下来……（下一步）</span></span></code></pre></div><hr><h3 id="公式2-会议发言-观点先行-论据-小结" tabindex="-1">公式2：会议发言 = 观点先行 + 论据 + 小结 <a class="header-anchor" href="#公式2-会议发言-观点先行-论据-小结" aria-label="Permalink to &quot;公式2：会议发言 = 观点先行 + 论据 + 小结&quot;">​</a></h3><p><strong>场景</strong>：开会讨论方案，需要发言</p><p><strong>正确示范</strong>：</p><blockquote><p>&quot;我认为应该选方案B（观点）。原因有两点：一是成本低30%，二是开发周期短两周（论据）。所以建议优先推进方案B（小结）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的观点是……（一句话）</span></span>
<span class="line"><span>原因是……（1. 2. 3.）</span></span>
<span class="line"><span>所以我建议……（结论）</span></span></code></pre></div><hr><h3 id="公式3-建议-肯定现有做法-补充建议-价值说明" tabindex="-1">公式3：建议 = 肯定现有做法 + 补充建议 + 价值说明 <a class="header-anchor" href="#公式3-建议-肯定现有做法-补充建议-价值说明" aria-label="Permalink to &quot;公式3：建议 = 肯定现有做法 + 补充建议 + 价值说明&quot;">​</a></h3><p><strong>场景</strong>：想给领导或同事提建议，但怕得罪人</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;你们这个方案不行，应该这样做……&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;这个方案的大方向很对（肯定），我有一个小建议（补充）：可以在XX环节加一个验证步骤（具体建议）。这样能减少返工（价值），大概节省2天时间（量化）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你们的XX做得很不错（肯定）</span></span>
<span class="line"><span>我有一个小建议（降低防御）</span></span>
<span class="line"><span>如果在XX地方……（具体建议）</span></span>
<span class="line"><span>这样可以……（价值说明）</span></span></code></pre></div><hr><h3 id="公式4-任务下达-目标-方法-资源" tabindex="-1">公式4：任务下达 = 目标 + 方法 + 资源 <a class="header-anchor" href="#公式4-任务下达-目标-方法-资源" aria-label="Permalink to &quot;公式4：任务下达 = 目标 + 方法 + 资源&quot;">​</a></h3><p><strong>场景</strong>：你是领导/组长，需要分配任务</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;这个你来做一下。&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;我们的目标是这周五之前完成用户调研报告（目标）。你可以先做用户访谈，再整理成报告（方法）。需要的话可以找小王协助访谈（资源）。有问题随时找我（开放）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：我们要……（清晰）</span></span>
<span class="line"><span>方法：你可以……（路径）</span></span>
<span class="line"><span>资源：需要XX支持找我……（兜底）</span></span></code></pre></div><hr><h3 id="公式5-解决问题-原因分析-方案对比-推荐方案" tabindex="-1">公式5：解决问题 = 原因分析 + 方案对比 + 推荐方案 <a class="header-anchor" href="#公式5-解决问题-原因分析-方案对比-推荐方案" aria-label="Permalink to &quot;公式5：解决问题 = 原因分析 + 方案对比 + 推荐方案&quot;">​</a></h3><p><strong>场景</strong>：汇报问题，需要领导拍板决策</p><p><strong>正确示范</strong>：</p><blockquote><p>&quot;目前有两个问题导致Delay（原因）。我想到两个方案（方案对比）：方案A需要3天，成本低但不治本；方案B需要5天，能彻底解决（优缺点）。我建议选方案B，因为XX更重要（推荐）。请领导决定（授权）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：目前有XX问题</span></span>
<span class="line"><span>方案A：……优……缺……</span></span>
<span class="line"><span>方案B：……优……缺……</span></span>
<span class="line"><span>建议：选方案B，因为……</span></span>
<span class="line"><span>请领导决定。</span></span></code></pre></div><hr><h3 id="公式6-安慰-表达共情-肯定付出-表达支持" tabindex="-1">公式6：安慰 = 表达共情 + 肯定付出 + 表达支持 <a class="header-anchor" href="#公式6-安慰-表达共情-肯定付出-表达支持" aria-label="Permalink to &quot;公式6：安慰 = 表达共情 + 肯定付出 + 表达支持&quot;">​</a></h3><p><strong>场景</strong>：同事/下属工作失误，情绪低落</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;没事没事，这不是你的错。&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;我知道你为这个项目付出了很多，结果不好肯定很难受（共情）。这个问题的原因很复杂，不是你一个人的问题（肯定）。接下来我们一起想办法，你不是一个人在扛（支持）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我知道……（共情对方的感受）</span></span>
<span class="line"><span>这不完全是你的问题……（降低愧疚）</span></span>
<span class="line"><span>接下来我们……（提供支持）</span></span></code></pre></div><hr><h3 id="公式7-谈判-找出共同利益-提出交换条件-寻求双赢" tabindex="-1">公式7：谈判 = 找出共同利益 + 提出交换条件 + 寻求双赢 <a class="header-anchor" href="#公式7-谈判-找出共同利益-提出交换条件-寻求双赢" aria-label="Permalink to &quot;公式7：谈判 = 找出共同利益 + 提出交换条件 + 寻求双赢&quot;">​</a></h3><p><strong>场景</strong>：跨部门资源协调，和合作方谈判</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;这个需求必须做！&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;我们有一个共同目标：让产品准时上线（共同利益）。我理解你们现在资源紧张（理解），我们这边可以先做XX让步（交换），这样你们也能减轻压力（双赢）。你看这样行不行？&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们的共同目标是……（找到交集）</span></span>
<span class="line"><span>我理解你的难处……（表达理解）</span></span>
<span class="line"><span>我们可以……（让步）</span></span>
<span class="line"><span>你们能不能……（交换）</span></span></code></pre></div><hr><h3 id="公式8-冲突处理-先处理情绪-后处理事情-约定规则" tabindex="-1">公式8：冲突处理 = 先处理情绪 + 后处理事情 + 约定规则 <a class="header-anchor" href="#公式8-冲突处理-先处理情绪-后处理事情-约定规则" aria-label="Permalink to &quot;公式8：冲突处理 = 先处理情绪 + 后处理事情 + 约定规则&quot;">​</a></h3><p><strong>场景</strong>：和同事发生争执，需要化解</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;你这样做就是不对！&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;我觉得我们现在都有点激动（情绪识别），先冷静一下（降温）。我的想法是……你的想法是……（还原事实）。我们找个时间坐下来，把分歧理清楚，定一个双方都能接受的方案（解决+规则）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我注意到我们都有些激动……（情绪命名）</span></span>
<span class="line"><span>先各自冷静一下……（降温）</span></span>
<span class="line"><span>我的观点是……你的观点是……（还原事实）</span></span>
<span class="line"><span>我们找个时间把分歧理清楚……（解决路径）</span></span></code></pre></div><hr><h3 id="公式9-批评-描述事实-表达期待-提供支持" tabindex="-1">公式9：批评 = 描述事实 + 表达期待 + 提供支持 <a class="header-anchor" href="#公式9-批评-描述事实-表达期待-提供支持" aria-label="Permalink to &quot;公式9：批评 = 描述事实 + 表达期待 + 提供支持&quot;">​</a></h3><p><strong>场景</strong>：需要指出别人的错误或不足</p><p><strong>错误示范</strong>：</p><blockquote><p>&quot;你怎么这么不负责任！&quot;</p></blockquote><p><strong>正确示范</strong>：</p><blockquote><p>&quot;报告里有三处数据错了（事实）。我希望下次提交前能核对一遍（期待）。需要的话我可以教你核对的方法（支持）。&quot;</p></blockquote><p><strong>话术模板</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我注意到……（只说事实，不扣帽子）</span></span>
<span class="line"><span>我希望……（正面说期待，而不是&quot;不要&quot;）</span></span>
<span class="line"><span>需要的话我可以……（提供帮助）</span></span></code></pre></div><hr><h2 id="三、高情商沟通底层心法" tabindex="-1">三、高情商沟通底层心法 <a class="header-anchor" href="#三、高情商沟通底层心法" aria-label="Permalink to &quot;三、高情商沟通底层心法&quot;">​</a></h2><h3 id="_3个底层原则" tabindex="-1">3个底层原则 <a class="header-anchor" href="#_3个底层原则" aria-label="Permalink to &quot;3个底层原则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>说明</th><th>练习方法</th></tr></thead><tbody><tr><td><strong>先解决情绪</strong></td><td>对方情绪没平复时，说什么都是对牛弹琴</td><td>被怼时先深呼吸3秒再开口</td></tr><tr><td><strong>结论先行</strong></td><td>先说结论，让对方决定要不要听细节</td><td>开口第一句不超过20字</td></tr><tr><td><strong>多说我理解</strong></td><td>&quot;我理解你的难处&quot;比&quot;但是&quot;好100倍</td><td>把&quot;但是&quot;换成&quot;而且&quot;</td></tr></tbody></table><h3 id="避免使用的句式" tabindex="-1">避免使用的句式 <a class="header-anchor" href="#避免使用的句式" aria-label="Permalink to &quot;避免使用的句式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>❌ 避免</th><th>✅ 替换</th></tr></thead><tbody><tr><td>&quot;但是……&quot;</td><td>&quot;而且……&quot;</td></tr><tr><td>&quot;你为什么不……&quot;</td><td>&quot;我想了解一下……&quot;</td></tr><tr><td>&quot;你总是……&quot;</td><td>&quot;这次的情况是……&quot;</td></tr><tr><td>&quot;我觉得你……&quot;</td><td>&quot;我感受到……&quot;</td></tr><tr><td>&quot;你错了&quot;</td><td>&quot;我的理解是……&quot;</td></tr><tr><td>&quot;你应该……&quot;</td><td>&quot;我建议……&quot;</td></tr></tbody></table><hr><h2 id="四、场景练习" tabindex="-1">四、场景练习 <a class="header-anchor" href="#四、场景练习" aria-label="Permalink to &quot;四、场景练习&quot;">​</a></h2><h3 id="场景1-领导问你为什么没完成" tabindex="-1">场景1：领导问你为什么没完成 <a class="header-anchor" href="#场景1-领导问你为什么没完成" aria-label="Permalink to &quot;场景1：领导问你为什么没完成&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌：&quot;客户那边一直拖着，我也催了……&quot;</span></span>
<span class="line"><span>✅：&quot;项目Delay了2天（结论）。主要原因是客户需求变更（原因）。</span></span>
<span class="line"><span>    目前完成度80%，我正在加班赶（行动）。预计周三补上（计划）。&quot;</span></span></code></pre></div><h3 id="场景2-同事不配合你的需求" tabindex="-1">场景2：同事不配合你的需求 <a class="header-anchor" href="#场景2-同事不配合你的需求" aria-label="Permalink to &quot;场景2：同事不配合你的需求&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌：&quot;你怎么这么不配合！&quot;</span></span>
<span class="line"><span>✅：&quot;我理解你现在手头事情很多（共情）。我们这边有个deadline是周五，</span></span>
<span class="line"><span>    如果能在这个时间前拿到支持，项目就能按时上线（说明价值）。</span></span>
<span class="line"><span>    需要我这边提供什么帮助吗？（提供支持）&quot;</span></span></code></pre></div><h3 id="场景3-会议上被质疑方案" tabindex="-1">场景3：会议上被质疑方案 <a class="header-anchor" href="#场景3-会议上被质疑方案" aria-label="Permalink to &quot;场景3：会议上被质疑方案&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌：&quot;这个方案很合理啊，你不懂……&quot;</span></span>
<span class="line"><span>✅：&quot;你的担忧很有道理（肯定）。关于你说的XX问题，</span></span>
<span class="line"><span>    我们当时是这样考虑的……（回应质疑）。你的建议很好，</span></span>
<span class="line"><span>    我们可以结合XX做一版优化，你看怎么样？（融入建议）&quot;</span></span></code></pre></div><hr><h2 id="五、快速检查清单" tabindex="-1">五、快速检查清单 <a class="header-anchor" href="#五、快速检查清单" aria-label="Permalink to &quot;五、快速检查清单&quot;">​</a></h2><p>开口之前，先过一遍：</p><ul><li>[ ] 结论说在前面了吗？</li><li>[ ] 我是在说事实还是在扣帽子？</li><li>[ ] 我是先处理情绪了吗？</li><li>[ ] 我有没有把&quot;但是&quot;换成&quot;而且&quot;？</li><li>[ ] 对方听完愿意配合吗？</li></ul>`,132)])])}const q=t(e,[["render",p]]);export{h as __pageData,q as default};
